function rob(nums) {
  const n = nums.length;
  if (n === 1) return nums[0];
  const memo = new Map();
  const best = (i, firstRobbed) => {             // the most from houses i..n-1
    if (i >= n) return 0;
    if (i === n - 1 && firstRobbed) return 0;    // the last house touches the first
    const key = i * 2 + (firstRobbed ? 1 : 0);
    if (memo.has(key)) return memo.get(key);
    const value = Math.max(best(i + 1, firstRobbed), nums[i] + best(i + 2, firstRobbed));
    memo.set(key, value);
    return value;
  };
  return Math.max(nums[0] + best(2, true), best(1, false));   // rob house 0, or don't
}

from functools import cache

def rob(nums):
    n = len(nums)
    if n == 1:
        return nums[0]

    @cache
    def best(i, first_robbed):            # the most from houses i..n-1
        if i >= n or (i == n - 1 and first_robbed):
            return 0                      # the last house touches the first
        return max(best(i + 1, first_robbed), nums[i] + best(i + 2, first_robbed))

    return max(nums[0] + best(2, True), best(1, False))   # rob house 0, or don't

