int best(int[] nums, int i, int firstRobbed) {   // the most from houses i..n-1
    int n = nums.length;
    if (i >= n || (i == n - 1 && firstRobbed == 1)) return 0;   // the last house touches the first
    if (memo[i][firstRobbed] != null) return memo[i][firstRobbed];
    return memo[i][firstRobbed] = Math.max(best(nums, i + 1, firstRobbed), nums[i] + best(nums, i + 2, firstRobbed));
}

