function rob(nums) {
  const n = nums.length;
  if (n === 1) return nums[0];
  const straight = (lo, hi) => {                 // House Robber on nums[lo..hi]
    let twoBack = 0, oneBack = 0;
    for (let i = lo; i <= hi; i++) {
      [twoBack, oneBack] = [oneBack, Math.max(oneBack, twoBack + nums[i])];
    }
    return oneBack;
  };
  return Math.max(straight(0, n - 2), straight(1, n - 1));   // skip the last, or skip the first
}

def rob(nums):
    n = len(nums)
    if n == 1:
        return nums[0]

    def straight(lo, hi):                 # House Robber on nums[lo..hi]
        two_back = one_back = 0
        for i in range(lo, hi + 1):
            two_back, one_back = one_back, max(one_back, two_back + nums[i])
        return one_back

    return max(straight(0, n - 2), straight(1, n - 1))   # skip the last, or skip the first

int rob(int[] nums) {
    int n = nums.length;
    if (n == 1) return nums[0];
    return Math.max(straight(nums, 0, n - 2), straight(nums, 1, n - 1));   // skip the last, or the first
}

int straight(int[] nums, int lo, int hi) {       // House Robber on nums[lo..hi]
    int twoBack = 0, oneBack = 0;
    for (int i = lo; i <= hi; i++) {
        int cur = Math.max(oneBack, twoBack + nums[i]);
        twoBack = oneBack;
        oneBack = cur;
    }
    return oneBack;
}

int straight(vector<int>& nums, int lo, int hi) {   // House Robber on nums[lo..hi]
    int twoBack = 0, oneBack = 0;
    for (int i = lo; i <= hi; i++) {
        int cur = max(oneBack, twoBack + nums[i]);
        twoBack = oneBack;
        oneBack = cur;
    }
    return oneBack;
}

int rob(vector<int>& nums) {
    int n = nums.size();
    if (n == 1) return nums[0];
    return max(straight(nums, 0, n - 2), straight(nums, 1, n - 1));   // skip the last, or the first
}
